  "5-5": {
    slides: [
      { type: "title", stage: "Unit 5 · Unit Review", eyebrow: "A1 · Ignite", title: "Unit Review", subtitle: "Talk briefly about hobbies and interests. No new language today." },
      { type: "vocab", stage: "Quick Start", heading: "Rapid-Fire Review", subheading: "Name hobbies, likes, dislikes, and when", items: [{ label: "Name 3 hobbies" }, { label: "Say something you like" }, { label: "Say something you don't like" }, { label: "Say when you do a hobby" }], instruction: [["🗣️", "Answer fast, one word is fine."]] },
      { type: "message", stage: "Review", heading: "Your Hobby Patterns", subheading: "Quick correction and review", lines: ["I like + -ing… I don't like + -ing…", "I do it after school. I do it on weekends."], instruction: [["👀", "Look at the patterns."], ["🗣️", "Say them with me."]] },
      { type: "dialogue", stage: "Controlled Practice", heading: "Mixed Prompts", subheading: "reading + evening / basketball + friends", turns: [{ who: "teacher", text: "drawing + home" }, { who: "student", text: "I draw at home." }], instruction: [["🗣️", "Build the sentence."]] },
      { type: "dialogue", stage: "Controlled Practice 2", heading: "One More Prompt", subheading: "Same idea, new prompt", turns: [{ who: "teacher", text: "reading + weekends (love)" }, { who: "student", text: "I love reading on weekends." }], instruction: [["🗣️", "Build the sentence."]] },
      { type: "factorcap", stage: "Final Challenge: Round 1", heading: "True or Cap?", statements: [{ text: "\"I don't like\" and \"I hate\" mean the exact same thing.", isTrue: false, explain: "Hate is much stronger -- don't like just means it's not for you, hate means you strongly dislike it." }, { text: "You can say a hobby and a time in the same sentence.", isTrue: true, explain: "Exactly -- \"I read in the evening\" combines both naturally." }, { text: "\"How often do you do it?\" is asking about frequency.", isTrue: true, explain: "Right -- that question expects an answer like every day or on weekends." }], instruction: [["🤔", "Decide: fact or cap?"]] },
      { type: "wheel", stage: "Final Challenge: Round 2", heading: "Spin & Answer", items: [{ label: "Name 3 hobbies" }, { label: "Say something you like" }, { label: "Say something you don't like" }, { label: "Say when you do a hobby" }], instruction: [["🔄", "Spin the wheel."], ["🗣️", "Answer for real."]] },
      { type: "factorcap", stage: "Final Challenge: Round 3", heading: "True or Cap? 2", statements: [{ text: "You can only describe hobbies you love, never ones you hate.", isTrue: false, explain: "You can talk about hobbies at any level -- love, like, don't like, or hate." }, { text: "\"After school\" and \"in the evening\" are both ways to say when.", isTrue: true, explain: "Exactly -- both answer the question \"when do you do it?\"" }, { text: "\"What's your favorite hobby?\" expects a yes/no answer.", isTrue: false, explain: "It expects a hobby name, not yes or no." }], instruction: [["🤔", "Decide: fact or cap?"]] },
      { type: "wheel", stage: "Final Challenge: Round 4", heading: "Spin Again", items: [{ label: "Name 3 hobbies" }, { label: "Say something you like" }, { label: "Say something you don't like" }, { label: "Say when you do a hobby" }], instruction: [["🔄", "Spin the wheel."], ["🗣️", "Answer for real."]] },
      { type: "practice", stage: "Independent Check", heading: "Tell Me About Your Hobbies", subheading: "Favorite hobby, when, who with, and one dislike", line: "My favorite hobby is ___. I do it ___, ___. I don't like ___.", instruction: [["🗣️", "Say the whole thing."], ["🙅", "No help this time."]] },
      { type: "landing", stage: "Unit Complete!", heading: "Unit 5 Complete!", caption: "You can name hobbies, express likes and dislikes, ask hobby questions, and describe your own routine." },
    ],
  },
