  "7-2": {
    slides: [
      { type: "title", stage: "Unit 7 · Lesson 2", eyebrow: "A1 · Ignite", title: "In My Room", subtitle: "Say where things are using basic prepositions." },
      { type: "dialogue", stage: "Warm-Up", heading: "Quick Question", subheading: "From last lesson", turns: [{ who: "teacher", text: "Where is your bed?" }, { who: "student", text: "My bed is ___." }], instruction: [["👂", "Listen."], ["🗣️", "Answer."]] },
      { type: "vocab", stage: "Getting Ready", heading: "Prepositions of Place", subheading: "New words for this unit", items: [{ label: "on / under" }, { label: "next to / near" }, { label: "behind" }, { label: "in front of" }], instruction: [["👀", "Look at the prepositions."], ["🗣️", "Say each one."]] },
      { type: "examples", stage: "Learn It", heading: "Where Is It?", subheading: "Object + preposition + place", rows: [["The book is on the desk.", "Where is the book?"], ["The bag is under the chair.", "Where is the bag?"]], instruction: [["👂", "Listen."], ["🗣️", "Repeat each question."]] },
      { type: "dialogue", stage: "Try It", heading: "Identify or Ask", subheading: "Identify the location, or ask where it is", turns: [{ who: "teacher", text: "The lamp is next to the bed." }, { who: "student", text: "Where is the book?" }], instruction: [["🗣️", "Identify or ask."]] },
      { type: "dialogue", stage: "Try It Again", heading: "One More Round", subheading: "Same idea, new location", turns: [{ who: "teacher", text: "The mirror is behind the door." }, { who: "student", text: "Where is the closet?" }], instruction: [["🗣️", "Identify or ask."]] },
      { type: "factorcap", stage: "Fix the Room", heading: "True or Cap?", statements: [{ text: "The pillow is under the desk.", isTrue: false, explain: "A pillow belongs on the bed, not under the desk -- that's cap!" }, { text: "The lamp is on the desk.", isTrue: true, explain: "That's a completely normal, believable place for a lamp." }, { text: "The shoes are on the bookshelf.", isTrue: false, explain: "Shoes go on the floor or in the closet, not on a bookshelf -- cap!" }], instruction: [["🤔", "Decide: fact or cap?"]] },
      { type: "factorcap", stage: "Fix the Room 2", heading: "True or Cap? 2", statements: [{ text: "The mirror is next to the closet.", isTrue: true, explain: "That's a normal, believable place for a mirror." }, { text: "The bed is in the closet.", isTrue: false, explain: "A bed is far too big to fit inside a closet -- cap!" }, { text: "The desk is in front of the window.", isTrue: true, explain: "That's a completely normal place for a desk." }], instruction: [["🤔", "Decide: fact or cap?"]] },
      { type: "factorcap", stage: "Fix the Room 3", heading: "True or Cap? 3", statements: [{ text: "The bookshelf is behind the bed.", isTrue: true, explain: "That's a normal, believable place for a bookshelf." }, { text: "The chair is under the mirror.", isTrue: false, explain: "A mirror is usually on a wall or closet -- a chair wouldn't fit under it -- cap!" }, { text: "The lamp is near the bed.", isTrue: true, explain: "That's a very common, believable place for a lamp." }], instruction: [["🤔", "Decide: fact or cap?"]] },
      { type: "factorcap", stage: "Fix the Room 4", heading: "True or Cap? 4", statements: [{ text: "The closet is on the desk.", isTrue: false, explain: "A closet is far too big to be on a desk -- cap!" }, { text: "The chair is next to the desk.", isTrue: true, explain: "That's a completely normal place for a chair." }, { text: "The bed is behind the mirror.", isTrue: false, explain: "A bed is too big to fit behind a wall mirror -- cap!" }], instruction: [["🤔", "Decide: fact or cap?"]] },
      { type: "practice", stage: "Exit Check", heading: "Where Is...?", subheading: "Answer 4 location questions in complete sentences", line: "The ___ is ___ the ___.", instruction: [["🗣️", "Answer the questions."], ["🙅", "No help this time."]] },
      { type: "landing", stage: "Wrap-Up", heading: "Nice Work!", caption: "You can now say where things are in a room. Next up: describing your own space." },
    ],
  },
