  "8-4": {
    slides: [
      { type: "title", stage: "Unit 8 · Lesson 4", eyebrow: "A1 · Ignite", title: "Ordering Food", subtitle: "Use a simple order in a food situation." },
      { type: "dialogue", stage: "Warm-Up", heading: "Quick Question", subheading: "Getting started", turns: [{ who: "teacher", text: "What would you order at a café?" }, { who: "student", text: "I'd like ___." }], instruction: [["👂", "Listen."], ["🗣️", "Answer."]] },
      { type: "vocab", stage: "Getting Ready", heading: "Ordering Phrases", subheading: "New phrases for this unit", items: [{ label: "Can I have...?" }, { label: "I'd like..." }, { label: "Anything else?" }, { label: "No, thank you." }], instruction: [["👀", "Look at the phrases."], ["🗣️", "Say each one."]] },
      { type: "dialogue", stage: "Learn It", heading: "A Full Order", subheading: "The model conversation", turns: [{ who: "student", text: "Hello. Can I have a burger, please?" }, { who: "teacher", text: "Sure. Anything else?" }, { who: "student", text: "Yes, a juice, please." }, { who: "teacher", text: "Anything else?" }, { who: "student", text: "No, thank you." }], instruction: [["👂", "Listen to the full order."], ["🗣️", "Repeat each line."]] },
      { type: "dialogue", stage: "Try It", heading: "Build an Order", subheading: "Choose one food and one drink", turns: [{ who: "teacher", text: "What would you like?" }, { who: "student", text: "Can I have a sandwich and a juice, please?" }], instruction: [["🗣️", "Build your order."]] },
      { type: "dialogue", stage: "Try It Again", heading: "One More Order", subheading: "Same idea, new items", turns: [{ who: "teacher", text: "What would you like?" }, { who: "student", text: "Can I have a pizza and a water, please?" }], instruction: [["🗣️", "Build your order."]] },
      { type: "factorcap", stage: "Café Counter Challenge", heading: "True or Cap?", statements: [{ text: "\"Can I have a burger, please?\" is a polite way to order.", isTrue: true, explain: "Exactly -- \"can I have... please\" is a polite ordering pattern." }, { text: "You should say \"give me a burger\" to be polite.", isTrue: false, explain: "That sounds rude -- \"can I have... please\" is the polite way." }, { text: "\"No, thank you\" is how you politely decline more items.", isTrue: true, explain: "Right -- that's exactly how you end an order politely." }], instruction: [["🤔", "Decide: fact or cap?"]] },
      { type: "factorcap", stage: "Café Counter Challenge 2", heading: "True or Cap? 2", statements: [{ text: "\"Anything else?\" is something the customer asks.", isTrue: false, explain: "It's usually the server asking the customer, not the other way around." }, { text: "You can order both food and a drink in the same order.", isTrue: true, explain: "Exactly -- \"a burger and a juice, please\" orders both." }, { text: "Saying \"please\" is optional when ordering.", isTrue: false, explain: "Please makes an order polite -- it's an important part of the pattern." }], instruction: [["🤔", "Decide: fact or cap?"]] },
      { type: "factorcap", stage: "Café Counter Challenge 3", heading: "True or Cap? 3", statements: [{ text: "\"I'd like a pizza\" is another polite way to order.", isTrue: true, explain: "Exactly -- \"I'd like...\" works just like \"can I have...\"" }, { text: "You must always order a drink with your food.", isTrue: false, explain: "Ordering just food, or just a drink, is completely fine." }, { text: "\"Sure, anything else?\" is something the server would say.", isTrue: true, explain: "Right -- that's the server checking if you want more." }], instruction: [["🤔", "Decide: fact or cap?"]] },
      { type: "factorcap", stage: "Café Counter Challenge 4", heading: "True or Cap? 4", statements: [{ text: "You can only order one item total.", isTrue: false, explain: "You can order as many items as you want, one at a time." }, { text: "\"Yes, a juice, please\" answers the question \"anything else?\"", isTrue: true, explain: "Exactly -- that's a complete, polite answer to that question." }, { text: "Ordering food always requires a long, complicated sentence.", isTrue: false, explain: "Short, simple sentences like \"can I have a burger, please?\" work perfectly." }], instruction: [["🤔", "Decide: fact or cap?"]] },
      { type: "practice", stage: "Exit Check", heading: "Order Independently", subheading: "One complete order, no script", line: "Can I have ___, please? Yes, a ___, please. No, thank you.", instruction: [["🗣️", "Place your order."], ["🙅", "No help this time."]] },
      { type: "landing", stage: "Wrap-Up", heading: "Nice Work!", caption: "You can now order food and drinks. Next up: Unit Review." },
    ],
  },
  "8-5": {
    slides: [
      { type: "title", stage: "Unit 8 · Unit Review", eyebrow: "A1 · Ignite", title: "Unit Review", subtitle: "Talk about food, drinks, and preferences. No new language today." },
      { type: "vocab", stage: "Quick Start", heading: "Food Speed Round", subheading: "5 foods, 3 drinks, 2 meals", items: [{ label: "5 foods" }, { label: "3 drinks" }, { label: "2 meals" }], instruction: [["🗣️", "Answer fast, one word is fine."]] },
      { type: "message", stage: "Review", heading: "Build Your Food Choices", subheading: "Breakfast, lunch, dinner, favorite drink", lines: ["For breakfast, I eat *bread*.", "My favorite drink is *juice*."], instruction: [["👀", "Look at the patterns."], ["🗣️", "Say them with me."]] },
      { type: "dialogue", stage: "Controlled Practice", heading: "Food Conversation", subheading: "Favorite food, dislikes, meals", turns: [{ who: "teacher", text: "What is your favorite food? What don't you like?" }, { who: "student", text: "My favorite food is pizza. I don't like fish." }], instruction: [["🗣️", "Answer both questions."]] },
      { type: "dialogue", stage: "Controlled Practice 2", heading: "One More Round", subheading: "Same idea, new details", turns: [{ who: "teacher", text: "What do you eat for breakfast? What do you like to drink?" }, { who: "student", text: "I eat cereal. I like juice." }], instruction: [["🗣️", "Answer both questions."]] },
      { type: "mystery", stage: "Final Challenge: Round 1", heading: "Guess the Food Fan", clues: ["This person's favorite food is pizza.", "This person doesn't like fish.", "This person drinks juice every day.", "This person's name starts with L."], answer: "Leo", instruction: [["🗣️", "Ask a question."], ["🤔", "Guess who it is."]] },
      { type: "dice", stage: "Final Challenge: Round 2", heading: "Roll & Say", dice: [{ name: "Food", items: ["pizza", "fish", "rice", "soup", "ice cream"] }], instruction: [["🎲", "Roll the die."], ["🗣️", "React to that food."]] },
      { type: "mystery", stage: "Final Challenge: Round 3", heading: "Guess Again", clues: ["This person's favorite food is noodles.", "This person doesn't like coffee.", "This person drinks tea every day.", "This person's name starts with M."], answer: "Mei", instruction: [["🗣️", "Ask a question."], ["🤔", "Guess who it is."]] },
      { type: "dice", stage: "Final Challenge: Round 4", heading: "Roll Again", dice: [{ name: "Food", items: ["pizza", "fish", "rice", "soup", "ice cream"] }], instruction: [["🎲", "Roll the die."], ["🗣️", "Say when you eat that."]] },
      { type: "practice", stage: "Independent Check", heading: "Tell Me About Your Food", subheading: "Favorite food, usual breakfast, a dislike", line: "My favorite food is ___. I usually eat ___ for breakfast. I don't like ___.", instruction: [["🗣️", "Say the whole thing."], ["🙅", "No help this time."]] },
      { type: "landing", stage: "Unit Complete!", heading: "Unit 8 Complete!", caption: "You can name foods and drinks, share preferences, talk about meals, and place an order." },
    ],
  },
